/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to a PDF file. &IsAuthorized = SecGAMIsAuthByFunctionalityKey.Udp(!'trnscargosww_Execute') If &IsAuthorized
LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState'
&Title = "Lista de Tabela de Cargos"
//Report Template Source Header &AppName = "DVelop Software Solutions" &Phone = !"+1 550 8923" &Mail = !"info@mail.com" &Website = !"http://www.web.com" &AddressLine1 = !"French Boulevard 2859" &AddressLine2 = !"Downtown" &AddressLine3 = !"Paris, France" Print printTitle End Footer &PageInfo = "Page: " + &Page.ToString().Trim() &DateInfo = "Date: " + &Today.ToFormattedString() Print printFooter End
Do 'PrintFilters'
Do 'PrintColumnTitles'
Do 'PrintData'
Do 'PrintFooter'
EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'CARDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carDescricao1.FromString(&GridStateDynamicFilter.Value) If not &carDescricao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltercarDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FiltercarDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &carDescricao = &carDescricao1 print printBlockFiltercarDescricao EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'CARDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carDescricao2.FromString(&GridStateDynamicFilter.Value) If not &carDescricao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltercarDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FiltercarDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &carDescricao = &carDescricao2 print printBlockFiltercarDescricao EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'CARDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carDescricao3.FromString(&GridStateDynamicFilter.Value) If not &carDescricao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltercarDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FiltercarDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &carDescricao = &carDescricao3 print printBlockFiltercarDescricao EndIf EndCase EndIf EndIf EndIf If not (&TFcarCodigo.IsEmpty() AND &TFcarCodigo_To.IsEmpty()) print printBlockTFcarCodigo &TFcarCodigo_To_Description = format('%1 (%2)', "Codigo", "WWP_TSTo") print printBlockTFcarCodigo_To EndIf If not &TFcarDescricao_Sel.IsEmpty() print printBlockTFcarDescricao_Sel Else If not &TFcarDescricao.IsEmpty() print printBlockTFcarDescricao EndIf EndIf &TFCarStatus_Sels.FromJson(&TFCarStatus_SelsJson) If not &TFCarStatus_Sels.Count = 0 &i = 1 For &TFCarStatus_Sel in &TFCarStatus_Sels If &i = 1 &TFCarStatus_SelDscs = '' Else &TFCarStatus_SelDscs += ', ' EndIf &FilterTFCarStatus_SelValueDescription = '' Do Case Case &TFCarStatus_Sel.ToString().Trim() = !"A" &FilterTFCarStatus_SelValueDescription = "Ativo"
Case &TFCarStatus_Sel.ToString().Trim() = !"I" &FilterTFCarStatus_SelValueDescription = "Inativo"
EndCase
&TFCarStatus_SelDscs += &FilterTFCarStatus_SelValueDescription &i += 1 EndFor print printBlockTFCarStatus_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnscargos order carDescricao when &OrderedBy = 1 AND &OrderedDsc = False order (carDescricao) when &OrderedBy = 1 AND &OrderedDsc = True order carCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (carCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order CarStatus when &OrderedBy = 3 AND &OrderedDsc = False order (CarStatus) when &OrderedBy = 3 AND &OrderedDsc = True
using trnscargosWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &carDescricao1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &carDescricao2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &carDescricao3, &TFcarCodigo , &TFcarCodigo_To, &TFcarDescricao, &TFcarDescricao_Sel, &TFCarStatus_Sels) &CarStatusDescription = '' Do Case Case CarStatus.ToString().Trim() = !"A" &CarStatusDescription = "Ativo"
Case CarStatus.ToString().Trim() = !"I" &CarStatusDescription = "Inativo"
EndCase
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnscargosWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnscargosWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnscargosWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFCARCODIGO" &TFcarCodigo.FromString(&GridStateFilterValue.Value) &TFcarCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARDESCRICAO" &TFcarDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARDESCRICAO_SEL" &TFcarDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARSTATUS_SEL" &TFCarStatus_SelsJson = &GridStateFilterValue.Value &TFCarStatus_Sels.FromJson(&TFCarStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforePrintLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
